// Boran's catalog: one category at a time, exact costs and a persistent preview selection.
Object.assign(RECIPE_MATERIALS,ADVANCED_MATERIALS);
const SMITH_CATEGORIES=[['sword','Silahlar'],['helmet','Miğferler'],['chest','Zırhlar'],['gloves','Eldivenler'],['shield','Kalkanlar'],['boots','Ayakkabılar'],['earring','Küpeler'],['accessory','Tılsım / Kolye']];
let smithMode='craft',smithCategory='chest',smithSelected='ironChest',smithCatalogScroll=0;
function smithPresent(){return p.area==='hub'&&$('service').open&&$('service').dataset.kind==='smith'&&nearestService()?.id==='smith'}
function recipeCosts(id){const i=itemInfo(id);if(!i)return null;const raw=id.startsWith('sword:')?{gold:i.cost,ore:i.ore,crystal:i.crystal}:GEAR[id]?{gold:GEAR[id].gold,ore:GEAR[id].ore,crystal:GEAR[id].crystal}:{gold:i.craftGold};const out={};Object.entries(raw).forEach(([key,n])=>{if(n)out[key]=n});Object.entries(RECIPE_MATERIALS[id]||{}).forEach(([key,n])=>out[key]=(out[key]||0)+n);return out}
function canAffordRecipe(id){const c=recipeCosts(id);return !!c&&Object.entries(c).every(([key,n])=>(key==='gold'?p.gold:p.inventory[key]||0)>=n)}
function spendRecipe(id){Object.entries(recipeCosts(id)).forEach(([key,n])=>{if(key==='gold')p.gold-=n;else p.inventory[key]-=n})}
function forgeableIds(category){if(category==='sword')return Object.keys(SWORDS).filter(id=>id!=='tide').sort((a,b)=>SWORDS[a].level-SWORDS[b].level||SWORDS[a].base-SWORDS[b].base).map(id=>'sword:'+id);if(category==='accessory')return Object.keys(ADVANCED_ACCESSORIES);return Object.keys(GEAR).filter(id=>!GEAR[id].starter&&GEAR[id].slot===category).sort((a,b)=>(GEAR[a].level||1)-(GEAR[b].level||1)||GEAR[a].gold-GEAR[b].gold)}
function forgeItem(id){const i=itemInfo(id);if(!i||!smithPresent()||itemCount(id)>0||p.level<(i.level||1)||!canAffordRecipe(id))return false;if(id.startsWith('sword:'))return forgeSword(id.slice(6));if(!GEAR[id]&&!ADVANCED_ACCESSORIES[id])return false;spendRecipe(id);p.inventory[id]=1;p.crafts=(p.crafts||0)+1;save();ui();renderService();toast(i.name+' üretildi. B ile kuşanabilirsin.');return true}
forgeGear=function(id){return GEAR[id]?forgeItem(id):false};
const equipBeforeTierCheck=equipGear;equipGear=function(id){if(GEAR[id]&&p.equipment[GEAR[id].slot]!==id&&p.level<(GEAR[id].level||1)){toast('Bu ekipman için seviye '+GEAR[id].level+' gerekli.');return false}return equipBeforeTierCheck(id)};
const accessoryBeforeTierCheck=equipAccessory;equipAccessory=function(id){if(p.accessory!==id&&p.level<(ITEMS[id]?.level||1)){toast('Bu aksesuar için seviye '+ITEMS[id].level+' gerekli.');return false}return accessoryBeforeTierCheck(id)};
function setCounts(){const counts={};Object.values(p.equipment).forEach(id=>{const key=GEAR[id]?.set;if(key)counts[key]=(counts[key]||0)+1});return counts}
function setBonusStats(){const count=setCounts(),s={armor:0,damage:0};Object.entries(EQUIPMENT_SETS).forEach(([key,set])=>set.bonuses.forEach(b=>{if((count[key]||0)>=b.pieces){s.armor+=b.armor;s.damage+=b.damage}}));return s}
const equipmentBeforeSets=equipmentStats;equipmentStats=function(){const a=equipmentBeforeSets(),b=setBonusStats();return{armor:a.armor+b.armor,damage:a.damage+b.damage}};
const rarityBeforeTier=itemRarity;itemRarity=function(id){if(GEAR[id]?.set||ADVANCED_ACCESSORIES[id]||['executionerEarring','eclipseEarring'].includes(id))return{id:'epic',name:'Destansı',rank:3,color:'#c5a1df'};if(id==='sentinelEarring')return{id:'rare',name:'Nadir',rank:2,color:'#92b8df'};return rarityBeforeTier(id)};
function smithStats(id){const i=itemInfo(id);if(!i)return{};if(id.startsWith('sword:'))return{damage:i.base+(p.swordUpgrades[id.slice(6)]||0)*7,armor:0,hp:0};if(GEAR[id]){const n=p.gearUpgrades[id]||0;return{armor:(i.armor||0)+n,damage:(i.damage||0)+(i.slot==='gloves'?n:0),hp:0}}return{armor:i.stats?.armor||0,damage:i.stats?.damage||0,hp:i.stats?.hp||0}}
function compareEquipment(id){const slot=itemSlot(id),old=equippedItem(slot),a=smithStats(id),b=smithStats(old);return{damage:(a.damage||0)-(b.damage||0),armor:(a.armor||0)-(b.armor||0),hp:(a.hp||0)-(b.hp||0)}}
function formatBonuses(stats){return [['armor','Savunma'],['damage','Hasar'],['hp','Azami can']].filter(([key])=>stats[key]).map(([key,label])=>`<span>${label} <b>+${stats[key]}</b></span>`).join('')||'<span>Temel ekipman</span>'}
function recipeHTML(id){return Object.entries(recipeCosts(id)||{}).map(([key,n])=>{const own=key==='gold'?p.gold:p.inventory[key]||0,name=key==='gold'?'Altın':ITEMS[key]?.name||key;return`<div class="forge-cost ${own>=n?'enough':'missing'}"><span>${name}</span><b>${own} / ${n}</b></div>`}).join('')}
function setInfoHTML(id){const key=GEAR[id]?.set;if(!key)return '';const set=EQUIPMENT_SETS[key],count=setCounts()[key]||0;return`<section class="forge-set"><b>${set.name} · ${count}/5 parça · ${set.role}</b>${set.bonuses.map(b=>`<p class="${count>=b.pieces?'active':''}">${b.pieces} parça: ${b.armor?'+'+b.armor+' savunma ':''}${b.damage?'+'+b.damage+' hasar':''}${count>=b.pieces?' · Etkin':''}</p>`).join('')}</section>`}
function renderSmith(){const root=$('serviceBody');let ids=smithMode==='craft'?forgeableIds(smithCategory):smithCategory==='sword'?(p.sword?['sword:'+p.sword]:[]):smithCategory==='accessory'?[]:Object.values(p.equipment).filter(id=>GEAR[id]?.slot===smithCategory);if(!ids.includes(smithSelected))smithSelected=ids[0]||null;const selected=itemInfo(smithSelected),owned=smithSelected&&itemCount(smithSelected)>0,stats=smithStats(smithSelected),diff=compareEquipment(smithSelected),level=selected?.level||1,cost=smithSelected?(smithSelected.startsWith('sword:')?{gold:60+p.weapon*45,ore:2+p.weapon}:gearUpgradeCost(smithSelected)):null,n=smithSelected?.startsWith('sword:')?p.weapon:p.gearUpgrades[smithSelected]||0;
 root.innerHTML=`<div class="smith-workshop"><div class="smith-modes"><button data-smith-mode="craft" class="${smithMode==='craft'?'selected':''}">Ekipman üret</button><button data-smith-mode="upgrade" class="${smithMode==='upgrade'?'selected':''}">Kuşanılanı güçlendir</button></div><div class="smith-layout"><nav class="smith-categories" aria-label="Demirci kategorileri">${SMITH_CATEGORIES.map(([key,name])=>`<button data-smith-category="${key}" class="${smithCategory===key?'selected':''}">${name}<small>${smithMode==='craft'?forgeableIds(key).length:key==='accessory'?'—':equippedItem(key)?1:0}</small></button>`).join('')}</nav><div class="smith-catalog"><div class="smith-category-title"><h3>${SMITH_CATEGORIES.find(([key])=>key===smithCategory)[1]}</h3><small>${smithMode==='craft'?'Tarif seç, malzemeleri incele, üret.':'Yalnızca kuşanılmış eşya güçlendirilir.'}</small></div>${ids.length?ids.map(id=>{const i=itemInfo(id),s=smithStats(id);return`<button class="forge-card ${smithSelected===id?'selected':''}" data-smith-select="${id}" aria-label="${i.name} tarifini incele">${itemIconHTML(id)}<span><small>${itemRarity(id).name} · Sv.${i.level||1}</small><b>${i.name}</b><em>${Object.entries(s).filter(([,v])=>v).map(([k,v])=>'+'+v+' '+({armor:'savunma',damage:'hasar',hp:'can'}[k])).join(' · ')}</em><i>${itemCount(id)?isEquipped(id)?'Kuşanılmış':'Çantanda':p.level<(i.level||1)?'Seviye '+i.level+' gerekli':canAffordRecipe(id)?'Üretime hazır':'Malzeme eksik'}</i></span></button>`}).join(''):`<div class="smith-empty">${smithCategory==='accessory'&&smithMode==='upgrade'?'Tılsımlar güçlendirilmez. Üretim sekmesinden yeni bir tılsım seçebilirsin.':'Bu kategoride kuşanılmış eşyan yok. B ile bir eşya kuşan.'}</div>`}</div><aside class="smith-detail">${selected?`<div class="smith-preview">${smithCategory==='accessory'?itemIconHTML(smithSelected,true):'<canvas id="smithHeroPreview" width="210" height="210" aria-label="Seçilen ekipmanın karakter üzerindeki görünümü"></canvas>'}</div><small>${itemRarity(smithSelected).name.toLocaleUpperCase('tr')} · SEVİYE ${level}</small><h3>${selected.name}</h3><div class="forge-stat-list">${formatBonuses(stats)}</div><p>${selected.description||''}</p><div class="forge-comparison"><small>Kuşanılmış parçaya göre · Set bonusu hariç</small>${[['armor','Savunma'],['damage','Hasar'],['hp','Azami can']].map(([key,title])=>`<span>${title}<b class="${diff[key]>0?'positive':diff[key]<0?'negative':''}">${diff[key]>0?'+':''}${diff[key]}</b></span>`).join('')}</div>${setInfoHTML(smithSelected)}${smithMode==='craft'?`<h4>Üretim malzemeleri</h4>${recipeHTML(smithSelected)}<button id="smithCraft" ${owned||p.level<level||!canAffordRecipe(smithSelected)?'disabled':''}>${owned?'Zaten sende var':p.level<level?'Seviye '+level+' gerekli':!canAffordRecipe(smithSelected)?'Malzeme eksik':'Eşyayı üret'}</button><p class="fine">Yalnızca başarılı üretimde malzemeler harcanır. Eşya çantana gelir.</p>`:`<h4>Güçlendirme +${n} → +${Math.min(10,n+1)}</h4>${Object.entries(cost).filter(([,v])=>v).map(([key,value])=>`<div class="forge-cost ${(key==='gold'?p.gold:p.inventory[key])>=value?'enough':'missing'}"><span>${key==='gold'?'Altın':ITEMS[key].name}</span><b>${key==='gold'?p.gold:p.inventory[key]} / ${value}</b></div>`).join('')}<p class="fine">${smithSelected.startsWith('sword:')?'+7 hasar':'+1 savunma'+(smithCategory==='gloves'?' ve +1 hasar':'')} · Garantili işlem · En fazla +10</p><button id="smithUpgrade" ${n>=10||Object.entries(cost).some(([key,v])=>(key==='gold'?p.gold:p.inventory[key])<v)?'disabled':''}>${n>=10?'Azami +10':'Güçlendir'}</button>`}`:'<p>İncelemek için bir tarif seç.</p>'}</aside></div></div>`;
 root.querySelectorAll('[data-smith-mode]').forEach(b=>b.onclick=()=>{smithMode=b.dataset.smithMode;smithSelected=null;smithCatalogScroll=0;renderService();$('service').scrollTop=0});root.querySelectorAll('[data-smith-category]').forEach(b=>b.onclick=()=>{smithCategory=b.dataset.smithCategory;smithSelected=null;smithCatalogScroll=0;renderService();$('service').scrollTop=0});root.querySelectorAll('[data-smith-select]').forEach(b=>b.onclick=()=>{smithCatalogScroll=root.querySelector('.smith-catalog')?.scrollTop||0;smithSelected=b.dataset.smithSelect;renderService();if(window.innerWidth<=780)$('serviceBody').querySelector('.smith-detail')?.scrollIntoView({behavior:'smooth',block:'start'})});if(selected){if($('smithCraft'))$('smithCraft').onclick=()=>forgeItem(smithSelected);if($('smithUpgrade'))$('smithUpgrade').onclick=()=>{serviceAction(smithSelected.startsWith('sword:')?'weapon':'upgradeGear',smithSelected);renderService()};paintSmithPreview(smithSelected)}paintItemIcons(root);const list=root.querySelector('.smith-catalog');if(list)list.scrollTop=smithCatalogScroll;
}
const renderBeforeWorkshop=renderService;renderService=function(){renderBeforeWorkshop();const smith=$('service').dataset.kind==='smith';$('service').classList.toggle('smith-open',smith);if(smith)renderSmith()};
